    correctKey: 'B',
    explanation: '監事監査は、管理組合の会計帳簿の記載内容と証憑書類（領収書、請求書、契約書等）との照合、預金口座の残高証明との突合、収支計算書・貸借対照表等の決算書類の内容の妥当性の検証等を通じて、会計処理が適正に行われているかを確認する作業である。通常、収支決算案が総会に提出される前に実施され、監事はその監査結果を総会において報告する。監査の過程で不正の疑いが発見された場合には、監事は臨時総会の招集等、必要な対応をとることが求められる。',
