    correctKey: 'D',
    explanation: '管理組合（区分所有法に基づき区分所有者全員で構成される団体）と自治会・町内会（地域コミュニティ活動を目的とする任意加入団体）は、法的性質・組織原理を異にする別個の団体である。両者が防災訓練や地域交流イベント等で連携・協力することは、良好な地域コミュニティの形成に資する有意義な取組みであるが、会計処理や意思決定のプロセスは、それぞれの団体の規約・規則に従い、明確に区別して整理することが、法的な混乱やトラブルを避ける上で望ましい。',
