    question: '事例問題である。マンションの管理組合が、コロナ禍を契機に総会の開催方法を見直し、書面決議とウェブ会議を併用したハイブリッド方式を導入することを検討している。この検討に関する次の記述のうち、最も適切なものはどれか。',
