    correctKey: 'D',
    explanation: 'マンション管理士は、区分所有法、標準管理規約、マンション管理適正化法、建物・設備等に関する専門知識を活かして管理組合を支援する専門家であるが、マンションの管理に関する最終的な意思決定権限は、あくまで区分所有者・管理組合（集会の決議）にある。したがって、マンション管理士は、専門知識に基づく分かりやすい情報提供と助言を通じて、区分所有者が必要な情報を十分に理解した上で、自ら主体的に判断・決定できるよう支援するという基本姿勢を持つことが重要である。この姿勢こそが、マンション管理士制度の根本的な理念（管理組合の自主性を尊重した専門的支援）を体現するものである。',
